  'terms.foot': 'آخر تحديث',
  'terms.intro': 'مرحبًا بك في SU8L DEVs. باستخدامك لهذه المنصة فأنت توافق على شروط الخدمة هذه. إذا لم توافق، لا تستخدم الخدمة.',
