  'terms.s1t': '1. نظرة عامة على الخدمة',
  'terms.s2d': 'تُنشأ الحسابات عبر مزوّدي المصادقة المدعومين. أنت مسؤول عن حماية بياناتك وعن كل النشاط تحت حسابك.',
  'terms.s2t': '2. الحساب والمصادقة',
  'terms.s3d': 'توافق على عدم إساءة استخدام الخدمة، أو مخالفة شروط أي لعبة يتصل بها البوت، أو إعادة بيع الوصول، أو محاولة الهندسة العكسية للمنصة. تُشارك بيانات حساب اللعبة خصوصًا مع المالك ولا تُخزن على هذه المنصة.',
  'terms.s3t': '3. الاستخدام المقبول',
  'terms.s4d': 'تُعالج المدفوعات حصريًا عبر PayPal Checkout. الاشتراكات النشطة تمنح فتحات البوت. فتحات الحساب الإضافية الدائمة هي مشتريات لمرة واحدة تعمل فقط بينما الاشتراك الأساسي نشط.',
  'terms.s4t': '4. الفوترة والاشتراكات',
  'terms.s5d': 'أكواد الخصم أحادية الاستخدام، وقد تخفّض فقط خطة الفئة العليا إلى السعر المعلن. لا تخفّض أكواد الخصم أبدًا الإضافات لمرة واحدة مثل فتحة الحساب الإضافية.',
  'terms.s5t': '5. أكواد الخصم',
  'terms.s6d': 'قد نعلّق أو ننهي الوصول عند مخالفة هذه الشروط. عند الإلغاء تحتفظ بالوصول حتى نهاية الفترة المدفوعة.',
