  'terms.foot': '[FR] Last updated',
  'terms.intro': '[FR] Welcome to SU8L DEVs. By accessing this platform you agree to these Terms of Service. If you do not agree, do not use the service.',
  'terms.s1d': '[FR] SU8L DEVs provides cloud-hosted game bot services ("the Service"). Subscriptions are billed via PayPal on a monthly or yearly cycle. The Service is provided on an "as is" and "as available" basis.',
  'terms.s1t': '[FR] 1. Service Overview',
