  'refund.foot': '[DE] This policy is part of the Terms of Service.',
  'refund.intro': '[DE] This policy governs refunds for the SU8L DEVs Cloud Bot Service.',
  'refund.s1d': '[DE] Because cloud resources are allocated to your bot immediately upon successful payment, all payments are strictly non-refundable once cloud allocation has occurred. Once your bot instance is provisioned and running, no refunds will be issued for any reason.',
  'refund.s1t': '[DE] 1. Strict No-Refund After Allocation',
  'refund.s2d': '[DE] If a PayPal transaction is denied or fails before completion, you will not be charged. Any authorization holds are released by PayPal according to their own policies.',
  'refund.s2t': '[DE] 2. Failed or Denied Payments',
  'refund.s3d': '[DE] In the unlikely event of a duplicate charge caused by our systems, we will refund the duplicate in full within 7 business days of verification.',
  'refund.s3t': '[DE] 3. Duplicate Charges',
  'refund.s4d': '[DE] Chargebacks on a provisioned bot are treated as a breach of these terms and may result in immediate suspension of service.',
  'refund.s4t': '[DE] 4. Fraudulent Transactions',
  'refund.s5d': '[DE] Questions about a payment should be raised via the internal ticket system within 14 days of the transaction. Refund policy decisions are final.',
  'refund.s5t': '[DE] 5. How to Request a Review',
  'refund.title': '[DE] Refund Policy',
