const dicts: Record<Lang, Dict> = { en, ar, fr, de, tr };

interface I18nContextValue {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (key: string) => string;
  dir: 'ltr' | 'rtl';
}

const I18nContext = createContext<I18nContextValue>({
  lang: 'en',
  setLang: () => {},
  t: (k) => k,
  dir: 'ltr',
});

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => {
    const saved = localStorage.getItem('su8l_lang');
    return saved === 'ar' || saved === 'en' || saved === 'fr' || saved === 'de' || saved === 'tr' ? (saved as Lang) : 'en';
  });

  const setLang = useCallback((l: Lang) => {
    setLangState(l);
    localStorage.setItem('su8l_lang', l);
  }, []);

  useEffect(() => {
    document.documentElement.lang = lang;
    document.body.dir = lang === 'ar' ? 'rtl' : 'ltr';
  }, [lang]);

  const t = useCallback(
    (key: string) => dicts[lang][key] ?? dicts.en[key] ?? key,
    [lang]
  );

  const value = useMemo<I18nContextValue>(
    () => ({ lang, setLang, t, dir: lang === 'ar' ? 'rtl' : 'ltr' }),
    [lang, setLang, t]
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  return useContext(I18nContext);
}

export function useLang() {
  return useContext(I18nContext);
}
